{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    nodes = case.get("nodes")
    required_symbols = case.get("required_symbols")
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError("invalid case fields")
    required_symbols = set(required_symbols)
    by_id = {}
    order = {}
    for index, node in enumerate(nodes):
        if not isinstance(node, dict):
            raise ValueError("invalid node")
        for field in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if field not in node:
                raise ValueError("missing node field")
        node_id = node["id"]
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError("invalid node id")
        if not isinstance(node["depth"], int) or isinstance(node["depth"], bool):
            raise ValueError("invalid depth")
        if not isinstance(node["removable"], bool):
            raise ValueError("invalid removable flag")
        by_id[node_id] = node
        order[node_id] = index
    for node in nodes:
        parent = node["parent"]
        if parent is not None and parent not in by_id:
            raise ValueError("unknown parent")
    roots = [node for node in nodes if node["parent"] is None]
    if len(roots) != 1:
        raise ValueError("tree must have one root")
    children = {node_id: [] for node_id in by_id}
    for node in nodes:
        if node["parent"] is not None:
            children[node["parent"]].append(node["id"])
    retained = set(by_id)
    removed = []
    candidates = sorted(by_id, key=lambda node_id: (-by_id[node_id]["depth"], node_id))
    for node_id in candidates:
        node = by_id[node_id]
        if not node["removable"] or node["parent"] is None:
            continue
        if node["symbol"] in required_symbols:
            continue
        if any(child in retained for child in children[node_id]):
            continue
        if node.get("grammar_valid", True) is False:
            continue
        if node.get("interestingness_preserved", True) is False:
            continue
        trial = retained - {node_id}
        if not all(any(by_id[item]["symbol"] == symbol for item in trial) for symbol in required_symbols):
            continue
        retained.remove(node_id)
        removed.append(node_id)
    return {"removed_node_ids": removed, "retained_node_ids": sorted(retained)}"}
